package test;

import org.eclipse.jface.viewers.IContentProvider;
import org.eclipse.jface.viewers.TableViewer;
import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Composite;

// A different content provider class, should not be affected by the rule
class CustomContentProvider implements IContentProvider {
    @Override public void dispose() {}
    @Override public void inputChanged(TableViewer viewer, Object oldInput, Object newInput) {}
}

public class NegativeTestClass {
    public void setupViewer(Composite parent) {
        TableViewer fTableViewer = new TableViewer(parent, SWT.MULTI);
        fTableViewer.setContentProvider(new CustomContentProvider()); // This should NOT match
    }
}
